<script setup lang="ts">import { Head,Link,router } from '@inertiajs/vue3';import { Plus } from '@lucide/vue';import { Button } from '@/components/ui/button';defineProps<{orders:{data:any[]};view:string;canManage:boolean}>();const filter=(view:string)=>router.get('/orders',{view},{preserveState:true,replace:true});const money=(v:number)=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(v);</script><template><Head title="Pedidos"/><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header class="flex justify-between"><div><h1 class="text-2xl font-semibold">Pedidos</h1><p class="text-sm text-muted-foreground">Entregas, reservas, anticipos y necesidad de producción.</p></div><Button v-if="canManage" as-child><Link href="/orders/create"><Plus/> Nuevo pedido</Link></Button></header><div class="flex flex-wrap gap-2"><Button v-for="item in [{v:'all',l:'Todos'},{v:'upcoming',l:'Próximas 24 h'},{v:'overdue',l:'Atrasados'},{v:'production',l:'Por producir'},{v:'ready',l:'Listos'}]" :key="item.v" size="sm" :variant="view===item.v?'default':'outline'" @click="filter(item.v)">{{item.l}}</Button></div><section class="overflow-x-auto rounded-xl border bg-card"><table class="w-full text-sm"><thead class="border-b bg-muted/40 text-left"><tr><th class="px-4 py-3">Pedido</th><th class="px-4 py-3">Cliente</th><th class="px-4 py-3">Entrega</th><th class="px-4 py-3">Estado</th><th class="px-4 py-3">Total / saldo</th></tr></thead><tbody class="divide-y"><tr v-for="order in orders.data" :key="order.id"><td class="px-4 py-3"><Link :href="`/orders/${order.id}`" class="font-medium text-amber-700 hover:underline">{{order.document_number}}</Link><p class="text-xs text-muted-foreground">{{order.priority}}</p></td><td class="px-4 py-3">{{order.customer}}</td><td class="px-4 py-3">{{order.due_at}}</td><td class="px-4 py-3">{{order.status_label}}</td><td class="px-4 py-3">{{money(order.total)}} / {{money(order.balance_amount)}}</td></tr></tbody></table><p v-if="!orders.data.length" class="p-10 text-center text-sm text-muted-foreground">No hay pedidos en esta vista.</p></section></main></template>
